declare(strict_types=1);require_once __DIR__.'/../api/shared/bootstrap.php';method('GET','POST');$f=__DIR__.'/../api/shared/config.local.php';$c=is_file($f)?require $f:[];$token=is_string($c['owner_setup_token']??null)?$c['owner_setup_token']:'';if(strlen($token)<32){http_response_code(503);exit('Setup disabled: add a random owner_setup_token (32+ characters) to config.local.php.');}if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($token,(string)($_POST['token']??''))){http_response_code(403);exit('Invalid setup token.');}$u=trim((string)($_POST['username']??''));$pw=(string)($_POST['password']??'');if(!preg_match('/^[A-Za-z0-9_.-]{4,80}$/',$u)||strlen($pw)<12||strlen($pw)>200){http_response_code(422);exit('Username must be 4–80 allowed characters; password must be 12+ characters.');}$p=db();if((int)$p->query('SELECT COUNT(*) FROM owner_users')->fetchColumn()){http_response_code(409);exit('Owner already exists. Delete owner/setup.php from hosting immediately.');}$p->prepare('INSERT INTO owner_users(username,password_hash,created_at) VALUES(?,?,UTC_TIMESTAMP())')->execute([$u,password_hash($pw,PASSWORD_DEFAULT)]);exit('Owner created. Delete owner/setup.php from hosting immediately and remove owner_setup_token from config.local.php.');} ?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>One-time Owner Setup</title><style>body{font:16px system-ui;background:#f7f7f0;color:#143b2b;max-width:440px;margin:8vh auto;padding:20px}form{display:grid;gap:14px;background:white;padding:24px;border-radius:16px}input,button{padding:12px;border:1px solid #ddd;border-radius:8px;font:inherit}button{background:#143b2b;color:white}</style><h1>One-time owner setup</h1><p>Create the owner login once, then delete this file from hosting.</p><form method="post"><label>Setup token<input name="token" required></label><label>Username<input name="username" required minlength="4" maxlength="80"></label><label>Password (12+ characters)<input name="password" type="password" required minlength="12" maxlength="200"></label><button>Create owner account</button></form></html>